-- ============================================================================
-- Dhawi Uwaid Family Tree — Dedicated Supabase Setup & 760-Member Seed Script
-- Target Project: https://nmsmbcfnlqvnzfprexbh.supabase.co
-- Tribe: ذوي عويض — من البصصة قبيلة الشدادين بني الحارث
-- Idempotent: Safe to run cleanly on a fresh database or re-run later.
-- ============================================================================

-- 1. Tables & Schema
CREATE TABLE IF NOT EXISTS public.tree_meta (
  id integer PRIMARY KEY DEFAULT 1 CHECK (id = 1),
  title text NOT NULL,
  tribe_subtitle text NOT NULL,
  edition_label text NOT NULL,
  total_nodes integer NOT NULL,
  descendant_count integer NOT NULL,
  ancestor_count integer NOT NULL,
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.family_members (
  id text PRIMARY KEY,
  name text NOT NULL,
  raw_name text NOT NULL,
  parent_id text REFERENCES public.family_members(id) ON DELETE SET NULL,
  branch_id text NOT NULL,
  branch_name text NOT NULL,
  generation integer NOT NULL,
  tier text NOT NULL,
  tier_label text NOT NULL,
  sort_order integer NOT NULL DEFAULT 0,
  bio_note text NOT NULL DEFAULT '',
  full_lineage text NOT NULL DEFAULT '',
  cx double precision,
  cy double precision,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_family_members_parent_id ON public.family_members(parent_id);
CREATE INDEX IF NOT EXISTS idx_family_members_branch_id ON public.family_members(branch_id);
CREATE INDEX IF NOT EXISTS idx_family_members_generation ON public.family_members(generation);

CREATE TABLE IF NOT EXISTS public.update_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  request_type text NOT NULL,
  branch_name text NOT NULL,
  target_person text NOT NULL,
  target_node_id text REFERENCES public.family_members(id) ON DELETE SET NULL,
  new_name text NOT NULL,
  submitter_name text NOT NULL DEFAULT '',
  notes text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')),
  created_at timestamptz NOT NULL DEFAULT now(),
  reviewed_at timestamptz
);

CREATE INDEX IF NOT EXISTS idx_update_requests_status_created ON public.update_requests(status, created_at DESC);

-- 2. Strict Row-Level Security (RLS) & API Grants
ALTER TABLE public.tree_meta ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.family_members ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.update_requests ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS tree_meta_public_read ON public.tree_meta;
CREATE POLICY tree_meta_public_read ON public.tree_meta
  FOR SELECT TO anon, authenticated USING (true);

DROP POLICY IF EXISTS family_members_public_read ON public.family_members;
CREATE POLICY family_members_public_read ON public.family_members
  FOR SELECT TO anon, authenticated USING (true);

DROP POLICY IF EXISTS update_requests_public_insert ON public.update_requests;
CREATE POLICY update_requests_public_insert ON public.update_requests
  FOR INSERT TO anon, authenticated
  WITH CHECK (
    status = 'pending'
    AND char_length(trim(request_type)) >= 2
    AND char_length(trim(branch_name)) >= 1
    AND char_length(trim(target_person)) >= 2
    AND char_length(trim(new_name)) >= 1
    AND char_length(request_type) <= 80
    AND char_length(branch_name) <= 80
    AND char_length(target_person) <= 200
    AND char_length(new_name) <= 200
    AND char_length(submitter_name) <= 150
    AND char_length(notes) <= 1000
  );

GRANT USAGE ON SCHEMA public TO anon, authenticated;
GRANT SELECT ON public.tree_meta, public.family_members TO anon, authenticated;
GRANT INSERT ON public.update_requests TO anon, authenticated;

-- 3. Upsert Tree Metadata
VALUES (1, 'شجرة ذوي عويض', 'من البصصة قبيلة الشدادين بني الحارث', 'النسخة المعتمدة والمحدّثة (٣ نوفمبر ٢٠٢٥ م / ١٢ جمادى الأولى ١٤٤٧ هـ)', 760, 749, 10)
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
